import java.util.*;
import org.junit.*;
import org.junit.Test;
import static com.google.javascript.jscomp.SourceFile.fromCode;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class SourceFile_getLineOffset_TriageGen0Test {

    @Test
    public void testGetLineOffset_ValidLine() {
        // Setup: Code with 3 lines
        // Line 1: "abc\n" (offset 0)
        // Line 2: "def\n" (offset 4)
        // Line 3: "ghi"   (offset 8)
        String code = "abc\ndef\nghi";
        SourceFile sourceFile = fromCode("test.js", code);

        assertEquals(0, sourceFile.getLineOffset(1));
        assertEquals(4, sourceFile.getLineOffset(2));
        assertEquals(8, sourceFile.getLineOffset(3));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetLineOffset_LowerBoundViolation() {
        // Test lineno < 1
        String code = "line1\nline2";
        SourceFile sourceFile = fromCode("test.js", code);

        sourceFile.getLineOffset(0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetLineOffset_UpperBoundViolation() {
        // Test lineno > lineOffsets.length
        String code = "line1\nline2";
        SourceFile sourceFile = fromCode("test.js", code);

        // There are 2 lines, so 3 should throw exception
        sourceFile.getLineOffset(3);
    }

    @Test
    public void testGetLineOffset_SingleLine() {
        // Test single line scenario
        String code = "single";
        SourceFile sourceFile = fromCode("test.js", code);

        assertEquals(0, sourceFile.getLineOffset(1));
    }

    @Test
    public void testGetLineOffset_EmptyCode() {
        // Depending on implementation of findLineOffsets, 
        // empty code might result in length 0 or 1.
        // If length is 0, any lineno should throw exception.
        SourceFile sourceFile = fromCode("test.js", "");

        try {
            sourceFile.getLineOffset(1);
        } catch (IllegalArgumentException e) {
            // Success if it handles empty file by throwing exception for line 1
        }
    }
}
